using System;using System.Collections.Generic;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using IdleRestaurant;
public static class ProgressionChecks{
 public static object Main(){var c=AssetDatabase.LoadAssetAtPath<RestaurantCatalog>(RestaurantProductionBuilder.CatalogPath);var checks=new List<string>();Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception(name);checks.Add(name);};var g=new RestaurantGame(c);g.State.outlets[0].waves=3;g.EnsureStarterManager();check(g.TeamCount==0,"Three services do not award the starter early");g.State.outlets[0].waves=4;g.EnsureStarterManager();check(g.TeamCount==1&&g.State.managerCopies[0]==1&&g.State.gems==0,"Fourth service awards exactly one free starter without tickets");g.EnsureStarterManager();check(g.TeamCount==1,"Starter cannot be awarded twice");check(g.Assign(0,0)&&g.State.outlets[0].managers[0]==0,"Starter assignment works before opening restaurant two");g.State.gems=100000;check(!g.CanRecruit(out _),"Paid-with-earned-tickets invitation still waits for restaurant two");g.State.cash=1e100;check(!g.Open(1),"Cash alone cannot skip restaurant service milestones");for(int next=1;next<40;next++){var o=g.State.outlets[next-1];o.waves=g.OutletServicesRequired(next);int n=g.OutletUpgradesRequired(next);for(int card=0;card<9;card++){o.upgrades[card]=Math.Min(30,n);n-=o.upgrades[card];}check(g.Open(next),"Expansion "+(next+1)+" is obtainable with stated requirements");}foreach(var o in g.State.outlets)o.waves=5000;var early=new List<int>{0};while(g.NextRecruitId()>=0){int id=g.NextRecruitId();if(early.Count<3)early.Add(c.managers[id].role);check(g.Recruit(0),"Earned invitation "+g.TeamCount);if(g.NextRecruitId()>=0){check(!g.CanRecruit(out _),"Another invitation waits for completed services");g.State.outlets[0].waves+=g.Balance.recruitServiceGap;}}check(early.SequenceEqual(new[]{0,1,2}),"First three teammates cover Orders, Kitchen and Dining");check(g.TeamCount==71&&g.State.managerCopies.All(n=>n==1),"All 71 teammates are obtainable exactly once");int gems=g.State.gems;check(!g.Recruit(0)&&g.State.gems==gems,"Complete team never consumes more tickets");var restored=new RestaurantGame(c,Newtonsoft.Json.JsonConvert.DeserializeObject<SaveState>(Newtonsoft.Json.JsonConvert.SerializeObject(g.State)));check(restored.TeamCount==71&&restored.State.outlets.Count(o=>o.open)==40&&restored.State.outlets[0].managers[0]==0&&restored.State.lastRecruitWaves==g.State.lastRecruitWaves,"Progression and early assignment survive save roundtrip");var report=new{utc=DateTime.UtcNow,status="PASS",checks,scope="Isolated seeded model checks only; separate FreshSession report covers actual earned live progression"};var root=Path.GetFullPath("Recordings/FreshSession051");Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"ProgressionChecks.json"),Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return new{status="PASS",checks=checks.Count};}
